function clearAudio(){if(audioURL)URL.revokeObjectURL(audioURL);audioURL=null;audioFile=null;if(audioElement)audioElement.pause();audioElement=null;audioSource=null;if(audioContext)audioContext.close();audioContext=null;$('audioUpload').value='';$('audioName').textContent='Silent export by default'}$('clearAudio').onclick=clearAudio;$('audioUpload').onchange=e=>{let f=e.target.files[0];if(!f)return;clearAudio();audioFile=f;audioURL=URL.createObjectURL(f);$('audioName').textContent=f.name};
function lock(yes){exporting=yes;document.querySelectorAll('button,input,select').forEach(e=>e.disabled=yes);zone.style.pointerEvents=yes?'none':'';if(!yes&&!supported.length)$('export').disabled=true}

$('clearEndcard').onclick=async()=>{if(exporting)return;state.endcard=null;$('endcardUpload').value='';await refreshAssets();changed()};
$('previewEndcard').onclick=()=>{if(exporting)return;playing=false;$('play').textContent='▶';time=duration()*.98;render(time)};
